rows=[]
for f in ('olympics','worlds','europeans','youth'):
    for r in csv.DictReader(open(f'data/{f}.csv',encoding='utf8')):
        a=ALIAS.get(r['athlete'].strip(),r['athlete'].strip())
        def num(x):
            try:return int(str(x).strip())
            except:return None
        cls=r['class'].strip();era='Mistral' if cls in ('Mistral','Lechner A-390') else ('RS:X' if cls=='RS:X' else ('iQFOiL' if cls=='iQFOiL' else 'Techno'))
        rows.append(dict(y=int(r['year']),comp=r['competition'].strip(),cls=cls,era=era,g=r['gender'].strip(),age=r['age_category'].strip(),a=a,he=HEB.get(a,''),pos=num(r['position']),n=num(r['field_size']),src=r['source_url'].strip(),note=r['notes'].strip()[:160]))
cov=[]
for f in ('olympics','worlds','europeans','youth'):
    for r in csv.DictReader(open(f'data/coverage_{f}.csv',encoding='utf8')):
        cov.append(dict(y=int(r['year']),comp=r['competition'].strip(),cls=r['class'].strip(),g=r['gender'].strip(),st=r['status'].strip(),src=r['source_url'].strip()))
json.dump(dict(rows=rows,cov=cov),open('data.json','w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
missing=sorted(set(r['a'] for r in rows if not r['he']));print('no hebrew:',missing)
print(len(rows),len(cov))
